    generated by build.ps1 from src/ - edit the sources, not this file
]]

local __VERSION = "1.0.0"
local __modules = {}
local __cache = {}
local __loading = {}
local function __import(name)
	local cached = __cache[name]
	if cached ~= nil then
		return cached
	end
	local loader = __modules[name]
	if not loader then
		error("[Hellspawn] unknown module '" .. tostring(name) .. "'", 2)
	end
	if __loading[name] then
		error("[Hellspawn] circular import of '" .. name .. "'", 2)
	end
	__loading[name] = true
	local result = loader(__import, __VERSION)
	__loading[name] = nil
	if result == nil then
		result = true
	end
	__cache[name] = result
	return result
end

