		library.Assets:ApplyIcon(grip, "grip")
		grip.ImageColor3 = theme:Get("TextMuted")
		local gripHovered = false
		Input.hover(grip, function(state)
			gripHovered = state
			Anim.tween(grip, { ImageColor3 = theme:Get(state and "Accent" or "TextMuted") }, 0.15)
