		ZIndex = 30,
		Parent = body,
	}))
	theme:Bind(Util.gradient(crown), { Color = "AccentGradient" })
	Glow.attach(library, crown, { Spread = 8, Strength = 0.35, ZIndex = 30 })

	-- crisp outline + faint inner bevel
	local outline = Util.passive(Util.create("Frame", {
