	if not Env.canFiles then
		return false
	end
	local current = ""
	for part in string.gmatch(path, "[^/\\]+") do
		current = current == "" and part or (current .. "/" .. part)
		local exists = false
		pcall(function()
			exists = Env.isfolder(current)
		end)
		if not exists then
			pcall(Env.makefolder, current)
		end
	end
