		local x, y = rng:range(0, size), rng:range(0, size)
		local len = rng:range(4, 18)
		local ang = rng:range(0, 2 * pi)
		wrapped({ { x, y }, { x + cos(ang) * len, y + sin(ang) * len } }, rng:range(0.3, 0.55), rng:range(0.25, 0.7), 1)
