	for _ = 1, 3 do
		local x, y = rng:range(0, size), rng:range(0, size)
		local ang = rng:range(0, 2 * pi)
		local pts = { { x, y } }
		for _ = 1, 36 do
			ang += rng:range(-0.35, 0.35)
			x += cos(ang) * 2.2
			y += sin(ang) * 2.2
			pts[#pts + 1] = { x, y }
