	for _ = 1, 300 do
		c:stamp(rng:range(0, size), rng:range(0, size), rng:range(0.25, 1.4), rng:range(0.2, 0.85), rng:next() < 0.7 and 1 or 0, "max", rng:range(0.3, 1))
