-- Dry-brush smear for the active tab
recipe("smear", 1, function()
	local w, h = 256, 40
	local c = Canvas.new(w, h)
	local rng = Rng.new(4242)
	local noise = Noise.new(rng, 32)
	local rows = table.create(h)
