recipe("cursor", 1, function()
	local c = Canvas.new(32, 32)
	local arrow = { 3, 2, 3, 24.5, 8.8, 19.4, 12.6, 28.2, 16.6, 26.4, 12.9, 17.8, 20.5, 17.8 }
	c:sdf(function(x, y)
		return Sdf.polygon(x, y, arrow) - 1.5
	end, { lum = 0 })
	c:sdf(function(x, y)
		return Sdf.polygon(x, y, arrow)
	end, { lum = 1 })
	return c
